  scheme: 'x402-v1';
  network: 'base' | 'arbitrum' | 'polygon';
  tokenAddress: string;
  recipientAddress: string;
  amountMinor: string;
  challengeNonce: string;
  expiresAt: number;
}

export interface X402SessionKeyConfig {
  agentAddress: string;
  sessionPrivateKeyPem: string;
  maxVelocityMinorPerTx: bigint;
  dailyCapMinor: bigint;
}

export class Http402AgentClient {
  public static async executeWithPayment(
    targetUrl: string,
    payload: Record<string, unknown>,
    sessionKey: X402SessionKeyConfig
  ): Promise<{ status: number; data: unknown }> {
    // 1. Initial Request probe
    const initialRes = await fetch(targetUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Agent-Protocol': 'x402/2026',
        'X-Agent-Id': sessionKey.agentAddress
      },
      body: JSON.stringify(payload)
    });

    if (initialRes.status !== 402) {
      return { status: initialRes.status, data: await initialRes.json() };
    }

    // 2. Parse RFC-compliant 402 Payment Challenge
    const paymentHeader = initialRes.headers.get('X-Payment-Required');
    if (!paymentHeader) {
      throw new Error('[Http402Client] Missing X-Payment-Required challenge header on 402 response');
    }

    const challenge = JSON.parse(Buffer.from(paymentHeader, 'base64').toString('utf8')) as X402PaymentChallenge;
    const paymentAmount = BigInt(challenge.amountMinor);

    // 3. Enforce Strict Velocity Cap
    if (paymentAmount > sessionKey.maxVelocityMinorPerTx) {
      throw new Error(`[Http402Client] Payment amount ${paymentAmount} exceeds velocity limit ${sessionKey.maxVelocityMinorPerTx}`);
    }

    // 4. Sign Autonomous Payment Proof with Session Key
    const proofPayload = `${sessionKey.agentAddress}:${challenge.recipientAddress}:${challenge.amountMinor}:${challenge.challengeNonce}:${challenge.expiresAt}`;
    const signer = crypto.createSign('SHA256');
    signer.update(proofPayload);
    signer.end();
    const proofSignature = signer.sign(sessionKey.sessionPrivateKeyPem, 'base64');

    // 5. Retrigger Request with Validated Payment Authorization
    const settledRes = await fetch(targetUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Agent-Protocol': 'x402/2026',
        'X-Agent-Id': sessionKey.agentAddress,
        'Authorization': `x402 ${Buffer.from(JSON.stringify({ challengeNonce: challenge.challengeNonce, signature: proofSignature, amountMinor: challenge.amountMinor })).toString('base64')}`
      },
      body: JSON.stringify(payload)
    });

    return { status: settledRes.status, data: await settledRes.json() };
  }
}
```

#### Blueprint 3: PostgreSQL M2M Ledger & Idempotency DDL (`database/m2m-ledger-schema.sql`)
```sql
-- Production PostgreSQL DDL for Agentic M2M Settlements
CREATE TABLE agent_wallets (
  agent_id VARCHAR(64) PRIMARY KEY,
  wallet_address VARCHAR(128) NOT NULL,
  currency VARCHAR(8) NOT NULL DEFAULT 'USD',
  balance_minor BIGINT NOT NULL DEFAULT 0 CHECK (balance_minor >= 0),
  hourly_velocity_cap_minor BIGINT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE m2m_settlement_escrows (
  escrow_id VARCHAR(64) PRIMARY KEY,
  task_id VARCHAR(64) NOT NULL,
  source_agent_id VARCHAR(64) NOT NULL REFERENCES agent_wallets(agent_id),
  worker_agent_id VARCHAR(64) NOT NULL REFERENCES agent_wallets(agent_id),
  critic_agent_id VARCHAR(64) NOT NULL,
  amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
  rail VARCHAR(32) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'RELEASED', 'REFUNDED')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finalized_at TIMESTAMPTZ
);

CREATE TABLE m2m_idempotency_records (
  external_id VARCHAR(128) PRIMARY KEY,
  escrow_id VARCHAR(64) NOT NULL REFERENCES m2m_settlement_escrows(escrow_id),
  settlement_ref VARCHAR(128) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Atomic Escrow Release Function
CREATE OR REPLACE FUNCTION finalize_m2m_escrow(
  p_escrow_id VARCHAR(64),
  p_action VARCHAR(24),
  p_external_id VARCHAR(128),
  p_settlement_ref VARCHAR(128)
) RETURNS BOOLEAN AS $$
DECLARE
  v_escrow m2m_settlement_escrows%ROWTYPE;
BEGIN
  -- Lock row for update to guarantee single-execution
  SELECT * INTO v_escrow
  FROM m2m_settlement_escrows
  WHERE escrow_id = p_escrow_id
  FOR UPDATE;

  IF NOT FOUND OR v_escrow.status <> 'PENDING' THEN
    RETURN FALSE;
  END IF;

  IF p_action = 'RELEASE' THEN
    UPDATE agent_wallets
    SET balance_minor = balance_minor + v_escrow.amount_minor,
        updated_at = now()
    WHERE agent_id = v_escrow.worker_agent_id;

    UPDATE m2m_settlement_escrows
    SET status = 'RELEASED', finalized_at = now()
    WHERE escrow_id = p_escrow_id;
  ELSE
    UPDATE agent_wallets
    SET balance_minor = balance_minor + v_escrow.amount_minor,
        updated_at = now()
    WHERE agent_id = v_escrow.source_agent_id;

    UPDATE m2m_settlement_escrows
    SET status = 'REFUNDED', finalized_at = now()
    WHERE escrow_id = p_escrow_id;
  END IF;

  INSERT INTO m2m_idempotency_records (external_id, escrow_id, settlement_ref)
  VALUES (p_external_id, p_escrow_id, p_settlement_ref);

  RETURN TRUE;
END;
$$ LANGUAGE plpgsql;
```

### Hard Guardrails (Declarative Invariants)
1. **Strict Session Key Velocity & Spend Limits**:
   - Every autonomous M2M transaction MUST operate under an ephemeral session key bounded by `maxVelocityMinorPerTx`, `dailyCapMinor`, and an absolute expiration epoch (`expiresAt`).
   - Any transaction exceeding single-tx velocity or daily cap MUST trigger an automatic hard rejection without calling payment gateways or signers.
2. **Quality Critic Milestone Gating for Escrow Finalization**:
   - No escrow funds may transition to `RELEASED` status without cryptographically attested proof of delivery and a verified Critic Quality Score (`criticQualityScore >= 0.85`).
3. **Atomic Double-Spend Prevention via Row Locks**:
   - All ledger updates and escrow finalizations MUST be executed inside an explicit database transaction with row-level locks (`SELECT ... FOR UPDATE` or atomic compare-and-swap) and recorded in an immutable idempotency log.
4. **Zero Float Currency Arithmetic**:
   - All balance calculations, fee deductions, and clearing amounts MUST use integer minor units (`bigint` or `NUMERIC(20, 0)`) to eliminate binary floating point rounding vulnerabilities.

### Sovereign Execution, Token Efficiency & Invariants
| Dimension | Sovereign Mandate & Deterministic Contract |
| :--- | :--- |
| **Frontier Model Cascade** | High Fast / High (`Gemini 4 Carbon`, `Gemini 4 Neon`, `Grok 4.7 High Fast`, `Claude Sonnet 5.5 High`, `Gemini 4 Pro`) |
| **Availability Fallback** | `Gemini 4 (Carbon/Hydrogen/Neon/Argon/Pro)` -> `Gemini 3.8 Flash`; `Claude Opus 5.5` -> `Claude Opus 4.6`; `Grok 4.7` -> `Grok 4.6 High Fast` (Zero unhandled missing-model errors) |
| **KV-Cache & Token Protocol** | Pin static instructions & schemas at prompt prefix (`kv-cache-prefix-optimizer`); pass surgical `CONTEXT_MAP.md` slices (<250 tokens/call) during Swarm Fan-Out |
| **SaaT CLI & MCP Dispatch** | CLI: `vibes skill exec agentic-m2m-settlement <audit\|eval\|verify\|generate\|blueprint>` / MCP: `vibes_skill_dispatch`, `vibes_critic_validate`, `vibes_self_heal`, `vibes_eval_sandbox`, `vibes_verify_invariants` |
| **NFR & Anti-Slop Invariants** | Zero OWASP Top 10 vectors, 0 hardcoded secrets, >= 90% branch coverage on domain logic, 0 Anti-Slop violations; 100% complete zero-placeholder output verified via `node scripts/check-anti-slop.js --strict` |

---


---

<a name="bahasa-indonesia"></a>
## Bahasa Indonesia

### Direktif Eksekutif & Kebutuhan Kliring M2M (Pergeseran 2026)
Pada swarm multi-agen skala perusahaan, sub-agen terspesialisasi kerap menugaskan agen lain untuk menangani tugas khusus (misal: red teaming otomatis, verifikasi formal, atau crawling dataset). Tanpa adanya rel kliring kriptografis yang mandiri, kolaborasi antar-agen akan terhenti karena menunggu tagihan manual manusia atau berisiko mengalami kebocoran anggaran yang tak terpantau.

**Agentic M2M Settlement** adalah protokol finansial standar produksi untuk transaksi otonom Mesin-ke-Mesin (Agent-to-Agent / A2A) dan Agen-ke-Infrastruktur (A2I). Protokol ini mendukung **Kliring Dual-Rail**:
1. **Rel Fiat (Standar Bank Indonesia SNAP BI & DOKU Payment Gateway)**: Kliring korporat resmi yang mendukung QRIS dinamis dan Virtual Account (BCA, Mandiri, BRI, BNI) dengan token B2B asimetris RSA-SHA256 serta tanda tangan layanan simetris HMAC-SHA512.
2. **Rel Mikro Stablecoin (USDC via Base/Arbitrum ERC-4337)**: Pembayaran mikro instan bernilai sub-sen memanfaatkan Smart Account dengan *session keys* berbatas waktu, batas kecepatan transaksi (*velocity caps*), dan daftar putih alamat tujuan.

