```typescript
// memory-manager.ts — unified interface over Mem0 + pgvector
import { addMemory, searchMemory, getAllMemories, deleteMemory } from "./mem0-client";
import { storeMemory, recallMemories } from "./memory-repository";

export type MemoryBackend = "mem0" | "pgvector" | "both";

export async function createMemory(
  userId: string,
  content: string,
  backend: MemoryBackend = "both",
  metadata: Record<string, unknown> = {},
): Promise<{ mem0Ids?: string[]; pgvectorId?: string }> {
  const results: { mem0Ids?: string[]; pgvectorId?: string } = {};

  if (backend === "mem0" || backend === "both") {
    const mem0Result = await addMemory(userId, [
      { role: "user", content: `Remember this: ${content}` },
    ]);
    results.mem0Ids = mem0Result.map((m) => m.id);
  }

  if (backend === "pgvector" || backend === "both") {
    results.pgvectorId = await storeMemory(userId, content, metadata);
  }

  return results;
}

export async function queryMemory(
  userId: string,
  query: string,
  backend: MemoryBackend = "both",
): Promise<Array<{ content: string; score: number; source: string }>> {
  const results: Array<{ content: string; score: number; source: string }> = [];

  if (backend === "mem0" || backend === "both") {
    const mem0Results = await searchMemory(userId, query, 5);
    results.push(
      ...mem0Results.map((m) => ({
        content: m.memory,
        score: m.score ?? 0.5,
        source: "mem0",
      })),
    );
  }

  if (backend === "pgvector" || backend === "both") {
    const pgResults = await recallMemories(userId, query, 5);
    results.push(
      ...pgResults.map((m) => ({
        content: m.content,
        score: m.similarity ?? 0.5,
        source: "pgvector",
      })),
    );
  }

  return results.sort((a, b) => b.score - a.score).slice(0, 10);
}

export async function purgeUserMemory(
  userId: string,
  backend: MemoryBackend = "both",
): Promise<void> {
  const { Pool } = await import("pg");
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });

  const tasks: Promise<void>[] = [];

  if (backend === "mem0" || backend === "both") {
    const { default: MemoryClient } = await import("mem0ai");
    const mem0 = new MemoryClient({ apiKey: process.env.MEM0_API_KEY! });
    tasks.push(mem0.deleteAll({ user_id: userId }).then(() => undefined));
  }

  if (backend === "pgvector" || backend === "both") {
    tasks.push(
      pool
        .query("DELETE FROM agent_memories WHERE user_id = $1", [userId])
        .then(() => undefined),
    );
  }

  await Promise.all(tasks);
}
```

### Hard Guardrails (Declarative Invariants)
1. **Mandatory User & Tenant Scoping on All Memory Lookups**:
   - Every semantic, episodic, and working memory query MUST mandate a non-null `userId` or `tenantId` filter (e.g. `WHERE user_id = $1` or `{ user_id }` parameter in Mem0/Letta).
   - Never perform unbounded cross-tenant vector scans or global similarity searches without an explicit tenancy filter.
2. **Relevance Thresholding & Cut-Off (`similarity >= 0.70`)**:
   - Semantic retrieval MUST enforce a strict cosine similarity lower bound (minimum 0.70) to prevent hallucinated or irrelevant memory drift from polluting the model's context window.
3. **Deterministic TTL on Ephemeral Working Context**:
   - Short-term episodic working memories and scratchpads MUST declare an `expiresAt` timestamp or TTL policy to prevent memory bloat and stale context replay.
4. **GDPR / PDP Art. 17 User Right-to-Forget Purge Path**:
   - Every memory architecture MUST provide a verified, atomic `purgeUserMemories(userId)` cascade across working, vector (pgvector/Qdrant), and episodic graph stores.

