    const page = await fetchPage(cursor);
    rowsExported += page.rows.length;
    cursor = page.nextCursor;

    ctx.heartbeat({
      lastProcessedCursor: cursor,
      rowsExported,
    } satisfies ExportCheckpoint);

    if (!cursor) break;
  }

  return { totalRows: rowsExported };
}
